package org.usbworkbench;
public class ReportSpeedTest {
 public static void main(String[] a){String[] reports={"ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad","Capacity: 123\nSector: 512\nAll sectors readable\n","السعة: 123\nالقطاع: 512\n","USB host / مضيف USB: true\nNative NTFS / محرك NTFS: true\n","MD5/SHA-1: legacy comparison only, not authenticity proof.\nMD5/SHA-1 للمقارنة القديمة فقط، وليستا إثبات أصالة.","GPT • CRC OK / سليم\nBytes: 100\n","Bytes\r\nSector: 512\r","First sector • read only\n123abc • file.txt\n","SHA-256 MATCH / تطابق","owned/file-بايت.txt\nDATA: unchanged"};int checks=0;for(String report:reports)for(boolean ar:new boolean[]{false,true}){String old=LegacyReportText.render(report,ar),now=ReportText.render(report,ar);if(!old.equals(now))throw new AssertionError("Mismatch "+report+" / "+old+" / "+now);checks++;}
 String row="Capacity: 32 GiB\nSector: 512\nPartition 1: type 7, sectors 65536\nowned-file.txt\n";StringBuilder large=new StringBuilder();for(int i=0;i<1000;i++)large.append(row);long start=System.nanoTime();for(int i=0;i<20;i++){String en=ReportText.render(large.toString(),false),ar=ReportText.render(large.toString(),true);if(!ar.contains("القسم 1: النوع 7")||!ar.contains("owned-file.txt")||!en.contains("Sector: 512"))throw new AssertionError("Report labels/data");checks++;}long ms=(System.nanoTime()-start)/1000000;if(ms>10000)throw new AssertionError("Unbounded report time "+ms);System.out.println("PASS: "+checks+" report parity/large-history/partition/data-preservation checks; "+ms+" ms");}
}
